import{_ as s,a0 as a,w as i,s as u,ao as d,I as p,x as t,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"来自欧洲的一个开源 3D 打印 VR 头盔项目 | LCTT x X-CMD","titleTemplate":false,"description":"来自欧洲的一个开源 3D 打印 VR 头盔项目 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"来自欧洲的一个开源 3D 打印 VR 头盔项目 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"来自欧洲的一个开源 3D 打印 VR 头盔项目 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220915 A Project For An Open Source 3D-Printed VR Headgear From Europe","title":"来自欧洲的一个开源 3D 打印 VR 头盔项目","tag":"202209","desc":""},"relativePath":"202209/20220915 A Project For An Open Source 3D-Printed VR Headgear From Europe.md","filePath":"[post].md"}'),l={name:"202209/20220915 A Project For An Open Source 3D-Printed VR Headgear From Europe.md"};function m(f,e,T,S,g,D){const r=a("Link");return i(),u("div",null,[e[15]||(e[15]=d('<h1 id="来自欧洲的一个开源-3d-打印-vr-头盔项目" tabindex="-1">来自欧洲的一个开源 3D 打印 VR 头盔项目 <a class="header-anchor" href="#来自欧洲的一个开源-3d-打印-vr-头盔项目" aria-label="Permalink to “来自欧洲的一个开源 3D 打印 VR 头盔项目”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/virtual-reality-4-1536x864.jpg" alt=""></p><blockquote><p>三家欧洲企业创建了一个 6 GHz WiFi 6E 无线开源虚拟现实头盔。</p></blockquote><p>捷克 3D 打印专家 Prusa Research 公司正在与模拟器开发商 Vrgineers 和英国的 Somnium Space 合作开发 Somnium VR ONE 头盔。这款产品可以连接或者独立使用，旨在尽可能地开放，来改变虚拟现实市场中受限的供应。</p><p>由于 Android 11 操作系统是一个开源的操作系统，其源代码是公开的，因此它将在不受限制的商业许可下出售。其中央处理单元是高通骁龙 XR2 CPU，支持 microSD 存储卡，并拥有 8GB 的LPDDR5 内存和 512GB UFS 闪存。</p><p>它采用新的 6 GHz 的 WiFi 6E 高带宽无线协议，而不是目前拥挤的 5GHz 和 2.4GHz WiFi频率，以实现更高的带宽和低延迟连接。它包括两个 3.2 英寸 2880RGB * 2880 快速液晶屏幕，具有 120 度水平视野和 100 度垂直视野。</p><p>它具有两个用于外部小工具的 USB-C 10 Gbit/s 链路，和一个 USB-C USB2.0 电池组（USB3.2 Gen2）。Somnium Space 与布拉格的 VRgineers 合作，在线销售电子产品和独有的镜头，使用户能够 3D 打印自己的头盔，此外，也会提供完整的头盔。</p><p>该企业于 2012 年在布拉格成立，已经拥有 700 多名员工。开源的 Prusa i3 design 是世界上使用最广泛的 3D 打印机，每月从布拉格直接向 160 多个国家运送超过 10000 台 Original Prusa 打印机。</p><p><ruby>合成训练环境<rt>Synthetic Training Environments</rt></ruby>（STE）是由捷克共和国的模拟器开发商 VRgineers 向企业和政府客户提供的。它创造了被称为 XTAL 的专业 8K 头盔，该头盔被 NASA、空客防务与航天公司和 BAE Systems 公司使用，目前在布拉格、布尔诺和拉斯维加斯拥有一支由 50 名专家组成的国际团队。</p><p>总部位于伦敦的 Somnium Space 是一个建立在区块链上的开放、社交和永久虚拟现实平台。由于其独特的 NFT 的去中心化经济，用户可以拥有、交易和交换数字商品而无需获得授权。它已经与高通公司和 Ultraleap 公司在 Lynx R-1 上进行了合作，这是一个独立的增强现实（AR）头盔设计。</p><hr>',11)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),o(r,{href:"https://www.opensourceforu.com/2022/09/a-project-for-an-open-source-3d-printed-vr-headgear-from-europe/"},{default:n(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/09/a-project-for-an-open-source-3d-printed-vr-headgear-from-europe/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=t("作者：",-1)),o(r,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:n(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),o(r,{href:"https://github.com/lkxed"},{default:n(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),o(r,{href:"https://github.com/zjsoftceo"},{default:n(()=>[...e[4]||(e[4]=[t("zjoftceo",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),o(r,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const P=s(l,[["render",m]]);export{C as __pageData,P as default};
